import { Component, OnInit } from '@angular/core';
import { ProductService, Produit } from '../../services/product.service';

@Component({
  selector: 'app-product-list',
  templateUrl: './product-list.component.html',
  styleUrls: ['./product-list.component.css']
})
export class ProductListComponent implements OnInit {

  products: Produit[] = [];
  selectedProduct: Produit | null = null; 

  constructor(private productService: ProductService) { } 

  ngOnInit(): void {
    this.loadProducts();
  }

  loadProducts(): void {
    this.productService.getProducts().subscribe(
      (data) => {
        this.products = data;
        this.selectedProduct = null; // Important pour annuler l'édition après la réussite
      },
      (error) => {
        console.error("Erreur lors du chargement des produits:", error);
      }
    );
  }

  selectProduct(product: Produit): void {
    this.selectedProduct = { ...product }; // Copie pour l'édition
  }

  cancelEdit(): void {
    this.selectedProduct = null;
  }

  deleteProduct(id: number): void {
    if (confirm("Êtes-vous sûr de vouloir supprimer ce produit ?")) {
      this.productService.deleteProduct(id).subscribe(
        () => {
          console.log(`Produit ${id} supprimé`);
          this.loadProducts(); // Recharge la liste
        },
        (error) => {
          console.error("Erreur de suppression du produit:", error);
          alert("Erreur lors de la suppression du produit.");
        }
      );
    }
  }
}
